"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96246"],{26886(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.ajuda_tamanho","status":422,"titulo":"Ajuda do campo acima do tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.item_formulario.ajuda_tamanho","requisitos":[],"oQueAconteceu":["A `ajuda` de um item do formul\xe1rio, ou de um campo de grupo, tem mais de 1000 caracteres depois de aparada. A ajuda \xe9 o texto que orienta o candidato no campo, e \xe9 opcional. A mensagem \xe9 \\"A ajuda do campo tem no m\xe1ximo 1000 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].ajuda` ou, no campo de um grupo, `grupos[g].subitens[j].ajuda`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","Nos modelos, a forma do item \xe9 conferida sem consultar o cat\xe1logo, e a recusa sai junto com as demais recusas da forma do item. Na grava\xe7\xe3o dos itens do formul\xe1rio, a recusa s\xf3 sai para o item cujo fato existe, \xe9 colet\xe1vel e combina com o tipo de campo: o item com fato desconhecido, [n\xe3o colet\xe1vel](/erros/uniplus.item_formulario.fato_nao_coletavel) ou com tipo de campo [incoerente](/erros/uniplus.item_formulario.tipo_de_campo_incoerente_com_dominio) \xe9 recusado por essa causa, e a ajuda dele s\xf3 \xe9 conferida depois que ela for corrigida. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Encurte a `ajuda` para at\xe9 1000 caracteres, ou retire-a: o campo funciona sem ajuda."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);